window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[104]={"id":"104","numero":104,"titre":"Sclérose en plaques","objectifs":[{"id":"104-1","rang":"B","rubrique":"Prévalence/Epidémiologie","titre":"Connaître les principaux éléments épidémiologiques de la sclérose en plaques (SEP)","contenu":"<p>La <span class=\"kw-def\"><strong>sclérose en plaques</strong></span> est une maladie <span class=\"kw-def\">chronique, auto-immune et inflammatoire du système nerveux central</span>. C'est la <strong>première cause de handicap neurologique non traumatique de l'adulte jeune</strong>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">1/1000</span> environ, soit près de <span class=\"kw-chiffre\">100 000 patients</span> en France</td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>prédominance <span class=\"kw-clinique\">féminine</span> nette : <span class=\"kw-chiffre\">3 femmes pour 1 homme</span></td></tr>\n          <tr><td><strong>Âge de début</strong></td><td>sujet jeune, entre <span class=\"kw-chiffre\">20 et 40 ans</span></td></tr>\n          <tr><td><strong>Géographie</strong></td><td><span class=\"kw-etio\">gradient Nord-Sud</span> : la SEP est plus fréquente lorsqu'on s'éloigne de l'équateur — <span class=\"kw-chiffre\">2 fois plus</span> dans les pays scandinaves que dans les pays méditerranéens</td></tr>\n          <tr>\n            <td><strong>Facteurs génétiques</strong></td>\n            <td>maladie multifactorielle : prédominance dans la <span class=\"kw-etio\">population caucasoïde</span> ; concordance de <span class=\"kw-chiffre\">30 %</span> chez les jumeaux monozygotes contre <span class=\"kw-chiffre\">2-3 %</span> chez les dizygotes ; gènes de susceptibilité liés au système <span class=\"kw-etio\">HLA</span></td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs environnementaux</strong></td>\n            <td><strong>Aggravants :</strong> <span class=\"kw-etio\">tabac</span> (augmente le risque et aggrave l'<span class=\"kw-clinique\">évolution</span>) ; <span class=\"kw-etio\">virus EBV</span> ; <span class=\"kw-etio\">carence en vitamine D</span> / faible ensoleillement ; <span class=\"kw-etio\">excès d'hygiène</span> (moindre exposition aux infections de l'enfance)<br><strong>Protecteur :</strong> <span class=\"kw-etio\">parasitoses</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Femme jeune (<span class=\"kw-chiffre\">3F/1H</span>, <span class=\"kw-chiffre\">20-40 ans</span>), gradient Nord-Sud, maladie multifactorielle (<span class=\"kw-etio\">génétique</span> HLA + environnement). La carence en <span class=\"kw-bio\">vitamine D</span> relie le gradient géographique au faible ensoleillement.</div>","frequence":2},{"id":"104-2","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principaux éléments physiopathologiques de la SEP","contenu":"<p>La SEP est une maladie <span class=\"kw-def\">inflammatoire auto-immune chronique du SNC</span>, à médiation cellulaire : un <span class=\"kw-def\">clone lymphocytaire autoréactif</span> cible la <span class=\"kw-def\">gaine de myéline</span>, présente en majeure partie dans la <span class=\"kw-def\">substance blanche</span>. L'<span class=\"kw-def\">axone</span> lui-même est aussi atteint (de façon primitive et secondaire).</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Au cours des poussées</strong></td>\n            <td>apparition de <span class=\"kw-def\">plaques de démyélinisation focale</span> disséminées dans la substance blanche du SNC — localisations préférentielles : <span class=\"kw-clinique\">nerf optique</span>, zones <span class=\"kw-clinique\">périventriculaires</span>, <span class=\"kw-clinique\">corps calleux</span>, <span class=\"kw-clinique\">cervelet</span>, <span class=\"kw-clinique\">moelle spinale</span>. Les symptômes dépendent de la localisation de la <span class=\"kw-clinique\">plaque</span>, ce qui explique leur diversité.</td>\n          </tr>\n          <tr>\n            <td><strong>Récupération</strong></td>\n            <td><span class=\"kw-def\">remyélinisation</span> possible par les <span class=\"kw-def\">oligodendrocytes</span> — c'est elle qui explique la récupération (± complète) après une poussée</td>\n          </tr>\n          <tr>\n            <td><strong>Phase progressive</strong></td>\n            <td>inflammation devenue plus <span class=\"kw-alerte\">diffuse</span> dans le SNC, conduisant à une <span class=\"kw-alerte\">atrophie cérébrale</span> et à une <span class=\"kw-alerte\">neurodégénérescence axonale</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 300\" role=\"img\" aria-label=\"Schéma physiopathologique de la sclérose en plaques. Au départ, l'axone est entouré d'une gaine de myéline intacte. Lors d'une poussée, un clone lymphocytaire auto-réactif attaque la myéline et crée une plaque de démyélinisation focale dans la substance blanche. Deux évolutions divergent ensuite. Voie favorable : la remyélinisation par les oligodendrocytes restaure la gaine et explique la récupération après la poussée. Voie défavorable : en phase progressive, l'inflammation diffuse entraîne une neurodégénérescence axonale et une atrophie cérébrale, source de handicap définitif.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">De la myéline saine à la <span class=\"kw-clinique\">plaque</span> : deux évolutions</text>\n          <rect class=\"fb-ok\" x=\"180\" y=\"38\" width=\"200\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"280\" y=\"58\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Myéline intacte</text>\n          <text class=\"tx-ok\" x=\"280\" y=\"74\" text-anchor=\"middle\" font-size=\"10.5\">axone gainé, conduction normale</text>\n          <line class=\"ln\" x1=\"280\" y1=\"84\" x2=\"280\" y2=\"100\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,106 275,98 285,98\"/>\n          <text class=\"tx-muted\" x=\"288\" y=\"98\" font-size=\"9.5\">poussée : clone lymphocytaire auto-réactif</text>\n          <rect class=\"fb-red\" x=\"166\" y=\"108\" width=\"228\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"128\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Plaque de démyélinisation</text>\n          <text class=\"tx-red\" x=\"280\" y=\"144\" text-anchor=\"middle\" font-size=\"10.5\">focale, substance blanche du SNC</text>\n          <line class=\"ln\" x1=\"280\" y1=\"156\" x2=\"280\" y2=\"172\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"150\" y1=\"172\" x2=\"410\" y2=\"172\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"150\" y1=\"172\" x2=\"150\" y2=\"190\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"150,196 145,188 155,188\"/>\n          <line class=\"ln\" x1=\"410\" y1=\"172\" x2=\"410\" y2=\"190\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"410,196 405,188 415,188\"/>\n          <rect class=\"fb-ok\" x=\"24\" y=\"198\" width=\"252\" height=\"76\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"150\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Remyélinisation</text>\n          <text class=\"tx-ok\" x=\"150\" y=\"236\" text-anchor=\"middle\" font-size=\"10.5\">par les oligodendrocytes</text>\n          <text class=\"tx-ok\" x=\"150\" y=\"252\" text-anchor=\"middle\" font-size=\"10.5\">→ récupération après la poussée</text>\n          <text class=\"tx-ok\" x=\"150\" y=\"268\" text-anchor=\"middle\" font-size=\"10.5\">(± complète)</text>\n          <rect class=\"fb-red\" x=\"284\" y=\"198\" width=\"252\" height=\"76\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"410\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Neurodégénérescence axonale</text>\n          <text class=\"tx-red\" x=\"410\" y=\"236\" text-anchor=\"middle\" font-size=\"10.5\">phase progressive : inflammation diffuse</text>\n          <text class=\"tx-red\" x=\"410\" y=\"252\" text-anchor=\"middle\" font-size=\"10.5\">→ atrophie cérébrale</text>\n          <text class=\"tx-red\" x=\"410\" y=\"268\" text-anchor=\"middle\" font-size=\"10.5\">→ handicap définitif</text>\n        </svg>\n        <figcaption><span class=\"kw-def\">Physiopathologie</span> de la SEP : la <span class=\"kw-def\">plaque de démyélinisation</span> peut soit cicatriser par <span class=\"kw-def\">remyélinisation</span> (récupération), soit évoluer vers la <span class=\"kw-alerte\">neurodégénérescence axonale</span> en phase progressive. Source : fiche source EDN item 104.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-clinique\">multiplicité des symptômes</span> n'est PAS synonyme de multiplicité des lésions : une seule <span class=\"kw-clinique\">plaque</span> bien placée (tronc cérébral) peut donner un tableau clinique riche.</div>","frequence":1},{"id":"104-3","rang":"A","rubrique":"Diagnostic positif","titre":"Citer les principaux symptômes révélateurs de la SEP","contenu":"<p>Les symptômes révélateurs sont <strong>très variables</strong>, fonction de la localisation de la <span class=\"kw-clinique\">plaque</span>. La SEP doit être évoquée devant un <span class=\"kw-def\">déficit neurologique d'installation subaiguë chez un adulte jeune</span>.</p>\n      <table >\n        <thead><tr><th>Mode de révélation</th><th>Tableau clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Myélite partielle</strong></span></td><td>fréquente ; <span class=\"kw-clinique\">signe de Lhermitte</span> ++ (décharges électriques le long du rachis à la flexion du cou)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NORB</strong></span> (névrite optique rétrobulbaire)</td><td>révèle la SEP dans <span class=\"kw-chiffre\">25 %</span> des cas ; baisse d'acuité visuelle unilatérale subaiguë douloureuse (voir obj-3)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Atteinte du tronc cérébral</strong></span></td><td><span class=\"kw-clinique\">vertige</span> par syndrome vestibulaire <span class=\"kw-clinique\">central</span> ; <span class=\"kw-clinique\">diplopie</span> ; <span class=\"kw-clinique\">ophtalmoplégie internucléaire</span> ++</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Atteinte cérébelleuse</strong></span></td><td><span class=\"kw-clinique\">ataxie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Atteinte hémisphérique</strong></span></td><td>déficit <span class=\"kw-clinique\">sensitif et/ou moteur</span> unilatéral</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Syndrome multifocal</strong></span></td><td>association d'emblée de plusieurs des tableaux ci-dessus</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Certains signes sont <span class=\"kw-alerte\">exceptionnels</span> dans la SEP et excluent quasiment le diagnostic : <span class=\"kw-alerte\">hémianopsie latérale homonyme</span>, cécité, surdité, atteinte du système nerveux périphérique, <span class=\"kw-clinique\">syndrome extrapyramidal</span>, aphasie, apraxie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres · 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":1},{"id":"104-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","contenu":"<p>La <span class=\"kw-etio\"><strong>NORB</strong></span> est une <span class=\"kw-def\">neuropathie optique inflammatoire démyélinisante</span>. C'est l'une des manifestations les plus fréquentes de la SEP, <span class=\"kw-clinique\">inaugurale dans 20 à 25 %</span> des cas. Le diagnostic est <strong>clinique</strong>.</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Baisse d'acuité visuelle</strong></span></td><td><strong>Installation :</strong> rapidement progressive sur quelques <span class=\"kw-chiffre\">heures à jours</span>, <span class=\"kw-alerte\">PAS brutale</span><br><strong>Latéralité :</strong> <span class=\"kw-clinique\">unilatérale</span> le plus souvent<br><strong>Importance :</strong> variable, mais souvent marquée (peut être &lt; 1/10)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Douleur</strong></span></td><td>présente dans <span class=\"kw-chiffre\">80 %</span> des cas ; <span class=\"kw-clinique\">rétro-oculaire</span> ; <span class=\"kw-clinique\">augmentée aux mouvements oculaires</span> ; oriente vers le caractère <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Examen de l'œil</strong></span></td><td><span class=\"kw-clinique\">œil blanc et indolore</span> (les douleurs sont rétro-orbitaires, pas oculaires)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Réflexe photomoteur</strong></span></td><td><span class=\"kw-clinique\">déficit pupillaire afférent relatif</span> (pupille de Marcus Gunn) du côté atteint — quasi constant, souvent seul signe objectif au <span class=\"kw-def\">stade</span> initial</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Fond d'œil</strong></span></td><td><span class=\"kw-clinique\">normal</span> dans <span class=\"kw-chiffre\">70 %</span> des cas (= forme rétrobulbaire) ; <span class=\"kw-clinique\">œdème papillaire</span> modéré dans <span class=\"kw-chiffre\">10-30 %</span> (= papillite, inflammation antérieure du nerf optique)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Champ visuel</strong></span></td><td><span class=\"kw-clinique\">scotome central ou cæcocentral</span> du côté atteint</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Vision des couleurs</strong></span></td><td><span class=\"kw-clinique\">dyschromatopsie d'axe rouge-vert</span> (test de Farnsworth)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'<span class=\"kw-alerte\">œil est blanc et indolore</span> : la douleur est <em>rétro-orbitaire</em> et augmentée aux mouvements, mais l'œil lui-même n'est ni rouge ni douloureux à la pression. Une baisse d'acuité visuelle <span class=\"kw-alerte\">brutale</span> n'est PAS une NORB.</div>\n      <div class=\"callout callout-warn\"><strong>Astuce QCM (ancien référentiel).</strong> Une <span class=\"kw-clinique\">inflammation intraoculaire modérée</span> (antérieure ou postérieure) est possible mais <span class=\"kw-chiffre\">rare (≈ 5 %)</span> dans la NORB. Si elle est présente, elle doit faire <span class=\"kw-alerte\">suspecter une cause infectieuse</span> (<span class=\"kw-etio\">syphilis</span>) ou <span class=\"kw-alerte\">inflammatoire systémique</span> (<span class=\"kw-etio\">sarcoïdose</span>) avant de l'attribuer à la SEP.</div>","frequence":2},{"id":"104-5","rang":"A","rubrique":"Définition","titre":"Savoir définir une poussée de la maladie","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> de la SEP combine deux événements de base à distinguer rigoureusement : la <span class=\"kw-def\">poussée</span> et la <span class=\"kw-def\">progression</span>.</p>\n      <table >\n        <thead><tr><th>Événement</th><th>Définition et critères</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Poussée</strong></span></td>\n            <td><strong>Définition :</strong> <span class=\"kw-def\">apparition</span> de nouveaux symptômes, <span class=\"kw-def\">réapparition</span> d'anciens symptômes, ou <span class=\"kw-def\">aggravation</span> de symptômes pré-existants<br><strong>Installation :</strong> subaiguë, sur quelques <span class=\"kw-chiffre\">heures à jours</span><br><strong>Durée :</strong> par définition <span class=\"kw-chiffre\">&gt; 24 h</span>, puis récupération ± complète<br><strong>Délai :</strong> 2 poussées sont séparées d'un intervalle <span class=\"kw-chiffre\">≥ 1 mois</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Progression</strong></span></td>\n            <td><span class=\"kw-alerte\">aggravation continue</span> de symptômes neurologiques sur une durée <span class=\"kw-chiffre\">≥ 6 mois</span>, sans récupération ; une fois commencée, elle ne s'interrompt plus — c'est la <span class=\"kw-alerte\">cause majeure de handicap</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> NE SONT PAS considérés comme une poussée : la <span class=\"kw-alerte\">fatigue isolée</span> et les <span class=\"kw-alerte\">symptômes survenant dans un contexte fébrile</span> (pseudo-poussée par phénomène d'Uhthoff — voir obj-18). Toujours vérifier les 2 critères chiffrés : durée <span class=\"kw-chiffre\">&gt; 24 h</span> et intervalle <span class=\"kw-chiffre\">≥ 1 mois</span>.</div>","frequence":1},{"id":"104-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux arguments du diagnostic de SEP","contenu":"<p>Le diagnostic de SEP repose sur les <span class=\"kw-def\">critères de McDonald 2017</span>. Aucun examen n'est spécifique : le diagnostic est un <strong>faisceau d'arguments</strong>.</p>\n      <table >\n        <thead><tr><th>Argument</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Dissémination spatiale</strong></span></td>\n            <td>atteinte de <span class=\"kw-clinique\">plusieurs zones du SNC</span> : mise en évidence cliniquement (ex. névrite optique + <span class=\"kw-def\">syndrome pyramidal</span>) ou par <span class=\"kw-imagerie\">IRM</span> — critère rempli si <span class=\"kw-chiffre\">≥ 1 lésion</span> dans <span class=\"kw-chiffre\">≥ 2 des 4 zones</span> stratégiques</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Dissémination temporelle</strong></span></td>\n            <td>succession d'épisodes dans le temps : nouvelle <span class=\"kw-imagerie\">IRM ≥ 3 mois</span> après, association de <span class=\"kw-radio\">lésions prenant et ne prenant pas le gadolinium</span>, ou présence de <span class=\"kw-bio\">bandes oligoclonales</span> dans le <span class=\"kw-bio\">LCS</span> (qui peut remplacer ce critère et permet un diagnostic plus précoce)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Absence d'arguments contre</strong></span></td>\n            <td><span class=\"kw-alerte\">absence d'altération de l'état général</span> et <span class=\"kw-alerte\">absence de meilleure explication</span> — l'exclusion des diagnostics différentiels est essentielle</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Si la dissémination temporelle est présente, le diagnostic peut être posé dès la <strong>1<sup>re</sup> poussée</strong> (lésions d'âges différents à l'<span class=\"kw-imagerie\">IRM</span>). La <span class=\"kw-def\">forme progressive d'emblée</span> répond à un critère temporel particulier : <span class=\"kw-clinique\">évolution</span> <span class=\"kw-chiffre\">&gt; 1 an</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> SEP = <span class=\"kw-def\">dissémination spatiale</span> + <span class=\"kw-def\">dissémination temporelle</span> + exclusion des différentiels. Les détails opérationnels des critères McDonald sont développés en obj-13.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres</em></p>","frequence":1},{"id":"104-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels de la SEP","contenu":"<p>Le diagnostic de SEP étant un diagnostic d'<strong>exclusion partielle</strong>, plusieurs cadres différentiels doivent être systématiquement écartés, surtout en présence de <span class=\"kw-alerte\">drapeaux rouges</span>.</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Inflammations isolées du SNC</strong> (principal DD)</td>\n            <td><span class=\"kw-etio\">névrite optique auto-immune idiopathique</span> ; <span class=\"kw-etio\">neuromyélite optique de Devic</span> (auto-anticorps anti-<span class=\"kw-bio\">AQP4</span> ou anti-<span class=\"kw-bio\">MOG</span>) ; <span class=\"kw-etio\">encéphalomyélite aiguë disséminée</span> (ADEM) de l'enfant — multifocale mais sans passage à la chronicité</td>\n          </tr>\n          <tr>\n            <td><strong>Atteintes neurologiques localisées</strong></td>\n            <td><span class=\"kw-etio\">tumeur</span>, <span class=\"kw-etio\">malformation vasculaire</span>, <span class=\"kw-etio\">compression médullaire</span> — l'imagerie fait la différence</td>\n          </tr>\n          <tr>\n            <td><strong>Maladies inflammatoires systémiques</strong></td>\n            <td><span class=\"kw-etio\">sarcoïdose</span> ; <span class=\"kw-etio\">maladie de Behçet</span> ; <span class=\"kw-etio\">lupus érythémateux disséminé</span> ; <span class=\"kw-etio\">syndrome de Gougerot-Sjögren</span> ; <span class=\"kw-etio\">artérites cérébrales</span></td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td><span class=\"kw-etio\">infections à tropisme neurologique</span> ; maladies cérébrovasculaires à attaques successives (peuvent simuler une SEP rémittente)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeaux rouges</span></strong> imposant la recherche d'un différentiel : <span class=\"kw-clinique\">altération de l'état général</span> ; atteinte d'un autre organe que le SNC ; <span class=\"kw-alerte\">syndrome inflammatoire biologique</span> (absent dans la SEP) ; <span class=\"kw-alerte\">méningite</span> ou absence de bandes oligoclonales dans le <span class=\"kw-bio\">LCS</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 211 — Sarcoïdose · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 340 — <span class=\"kw-def\">AVC</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"104-8","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les différents modes évolutifs de la SEP","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> globale de la SEP est <span class=\"kw-def\">polymorphe</span>, reflet de l'interaction entre les <span class=\"kw-def\">poussées</span> et la <span class=\"kw-def\">progression</span> continue du handicap. On distingue <strong>3 formes cliniques</strong>.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Rémittente-récurrente</strong></span><br>(<span class=\"kw-chiffre\">85 %</span> des formes de début)</td>\n            <td><strong>Âge de début :</strong> en moyenne <span class=\"kw-chiffre\">30 ans</span><br><strong>Manifestations :</strong> composée <span class=\"kw-clinique\">exclusivement de poussées</span>, pouvant laisser des séquelles qui restent stables entre les poussées</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Secondairement progressive</strong></span></td>\n            <td><strong>Délai :</strong> <span class=\"kw-clinique\">évolution</span> naturelle tardive de la forme rémittente, en moyenne <span class=\"kw-chiffre\">15 à 20 ans après</span> le début<br><strong>Manifestations :</strong> phase de <span class=\"kw-def\">progression</span> succédant à la phase rémittente — peut toucher tous les patients initialement rémittents</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Primaire progressive</strong></span><br>(<span class=\"kw-chiffre\">15 %</span> des formes de début)</td>\n            <td><strong>Âge de début :</strong> plus tardif, vers <span class=\"kw-chiffre\">40 ans</span><br><strong>Manifestations :</strong> <span class=\"kw-alerte\">progression d'emblée, sans poussée</span> ; atteinte habituellement <span class=\"kw-clinique\">médullaire</span> (<span class=\"kw-ttt\">réduction</span> progressive du <span class=\"kw-clinique\">périmètre de marche</span> par <span class=\"kw-clinique\">paraparésie spastique</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 340\" role=\"img\" aria-label=\"Courbes handicap-temps des trois modes évolutifs de la sclérose en plaques. La forme rémittente-récurrente débute en moyenne vers 30 ans par des poussées successives séparées de phases stables, dessinant un escalier ; elle représente 85 pour cent des formes de début. Après en moyenne 15 à 20 ans, elle peut évoluer vers une forme secondairement progressive où le handicap s'aggrave de façon continue. La forme primitivement progressive débute plus tard, vers 40 ans, par une progression continue du handicap d'emblée, sans poussée, et représente 15 pour cent des formes de début.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Handicap au cours du temps selon le mode évolutif</text>\n          <line class=\"ln\" x1=\"60\" y1=\"44\" x2=\"60\" y2=\"230\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"60\" y1=\"230\" x2=\"535\" y2=\"230\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"60,38 55,48 65,48\"/>\n          <polygon class=\"ah\" points=\"541,230 531,225 531,235\"/>\n          <text class=\"tx-muted\" x=\"50\" y=\"140\" text-anchor=\"middle\" font-size=\"10.5\" transform=\"rotate(-90 50 140)\">Handicap</text>\n          <text class=\"tx-muted\" x=\"528\" y=\"248\" text-anchor=\"end\" font-size=\"10.5\">Temps (âge)</text>\n          <text class=\"tx-muted\" x=\"95\" y=\"248\" text-anchor=\"middle\" font-size=\"10\">~<span class=\"kw-chiffre\">30 ans</span></text>\n          <text class=\"tx-muted\" x=\"305\" y=\"248\" text-anchor=\"middle\" font-size=\"10\">+<span class=\"kw-chiffre\">15-20 ans</span></text>\n          <text class=\"tx-muted\" x=\"135\" y=\"248\" text-anchor=\"middle\" font-size=\"10\">~<span class=\"kw-chiffre\">40 ans</span></text>\n          <polyline class=\"ln\" points=\"95,218 135,218 135,194 180,194 180,194 220,194 220,170 265,170 265,148 305,148\" fill=\"none\" stroke-width=\"2.5\"/>\n          <polyline class=\"ln\" points=\"305,148 345,128 385,108 435,84 495,60\" fill=\"none\" stroke-width=\"2.5\"/>\n          <polyline class=\"ln\" points=\"135,218 190,194 245,168 300,142 360,112 425,78 495,52\" fill=\"none\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n          <line class=\"ln\" x1=\"305\" y1=\"50\" x2=\"305\" y2=\"230\" stroke-width=\"1.2\" stroke-dasharray=\"3 4\"/>\n          <text class=\"tx-muted\" x=\"312\" y=\"60\" font-size=\"9.5\">passage</text>\n          <line class=\"ln\" x1=\"60\" y1=\"276\" x2=\"535\" y2=\"276\" stroke-width=\"1\"/>\n          <rect class=\"fb-teal\" x=\"62\" y=\"286\" width=\"13\" height=\"13\" rx=\"3\"/>\n          <text class=\"tx-title\" x=\"81\" y=\"296\" font-size=\"10.5\">Rémittente-récurrente —<span class=\"kw-chiffre\"> 85 %</span>, début ~<span class=\"kw-chiffre\">30 ans</span> : escalier de poussées</text>\n          <rect class=\"fb-amber\" x=\"62\" y=\"306\" width=\"13\" height=\"13\" rx=\"3\"/>\n          <text class=\"tx-title\" x=\"81\" y=\"316\" font-size=\"10.5\">Secondairement progressive —<span class=\"kw-chiffre\"> 15-20 ans</span> après : aggravation continue</text>\n          <rect class=\"fb-red\" x=\"62\" y=\"326\" width=\"13\" height=\"13\" rx=\"3\"/>\n          <text class=\"tx-title\" x=\"81\" y=\"336\" font-size=\"10.5\">Primitivement progressive (- - -) —<span class=\"kw-chiffre\"> 15 %</span>, début ~<span class=\"kw-chiffre\">40 ans</span>, sans poussée</text>\n        </svg>\n        <figcaption>Modes évolutifs de la SEP : la forme <span class=\"kw-def\">rémittente</span> (poussées) peut devenir <span class=\"kw-alerte\">secondairement progressive</span> après <span class=\"kw-chiffre\">15-20 ans</span> ; la forme <span class=\"kw-alerte\">primitivement progressive</span> aggrave le handicap d'emblée, sans poussée. Source : fiche source EDN item 104.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Forme <span class=\"kw-def\">rémittente</span> = poussées seules, début <span class=\"kw-chiffre\">30 ans</span>, <span class=\"kw-chiffre\">85 %</span>. Forme <span class=\"kw-def\">primaire progressive</span> = progression d'emblée, début <span class=\"kw-chiffre\">40 ans</span>, <span class=\"kw-chiffre\">15 %</span>, paraparésie spastique. La forme <span class=\"kw-def\">secondairement progressive</span> est l'<span class=\"kw-clinique\">évolution</span> tardive de la rémittente.</div>","frequence":3},{"id":"104-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic général de la SEP","contenu":"<p>Le <span class=\"kw-def\">pronostic</span> de la SEP est <span class=\"kw-alerte\">imprévisible et variable</span>, des formes bénignes / pauci-symptomatiques aux formes sévères avec dépendance complète. Point essentiel : l'<span class=\"kw-clinique\">espérance de vie n'est que peu réduite</span>.</p>\n      <p>Une <span class=\"kw-def\">maladie active</span> est définie par la présence, <strong>au cours de l'année précédente</strong>, d'au moins l'un des éléments suivants : une <span class=\"kw-def\">poussée</span> (activité clinique) ou de <span class=\"kw-radio\">nouvelles lésions T2</span> / des <span class=\"kw-radio\">lésions rehaussées par le gadolinium</span> (activité radiologique).</p>\n      <table >\n        <thead><tr><th>Facteurs de bon <span class=\"kw-def\">pronostic</span></th><th>Facteurs de mauvais pronostic</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">âge de début jeune</span></td>\n            <td><span class=\"kw-alerte\">âge de début &gt; 40 ans</span></td>\n          </tr>\n          <tr>\n            <td>mode <span class=\"kw-clinique\">rémittent</span></td>\n            <td>forme <span class=\"kw-alerte\">primitivement progressive</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">long délai entre les 2 premières poussées</span></td>\n            <td><span class=\"kw-alerte\">intervalle court entre les crises</span></td>\n          </tr>\n          <tr>\n            <td>début par une <span class=\"kw-etio\">NORB</span> ou une atteinte <span class=\"kw-clinique\">sensitive</span> ; <span class=\"kw-imagerie\">IRM normale</span> au début</td>\n            <td><span class=\"kw-alerte\">atteinte motrice initiale</span> ; <span class=\"kw-alerte\">charge lésionnelle IRM élevée</span> ; signes <span class=\"kw-alerte\">cérébelleux</span> ; <span class=\"kw-alerte\">sexe masculin</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Bon <span class=\"kw-def\">pronostic</span> = jeune, rémittent, début NORB/sensitif, <span class=\"kw-imagerie\">IRM</span> initiale propre. Mauvais pronostic = &gt;<span class=\"kw-chiffre\"> 40 ans</span>, progressif, atteinte motrice/cérébelleuse, charge lésionnelle, homme.</div>","frequence":1},{"id":"104-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt de la ponction lombaire et des potentiels évoqués visuels (PEV) pour le diagnostic de SEP","contenu":"<p>Aucun examen complémentaire n'est un <span class=\"kw-def\">marqueur spécifique</span> de la SEP. PL et PEV apportent des <strong>arguments d'appoint</strong>.</p>\n      <p><strong>Examen du <span class=\"kw-bio\">LCS</span> (<span class=\"kw-bio\">ponction lombaire</span>)</strong> — non systématique si les critères <span class=\"kw-imagerie\">IRM</span> sont remplis ; il peut <span class=\"kw-def\">remplacer le critère de dissémination temporelle</span>. Il met en évidence une inflammation du SNC et élimine les différentiels.</p>\n      <table >\n        <thead><tr><th>Marqueur du <span class=\"kw-bio\">LCS</span></th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Bandes oligoclonales</strong></span></td><td>en <span class=\"kw-bio\">iso-électrofocalisation</span> ou <span class=\"kw-bio\">immunofixation</span> ; présentes dans <span class=\"kw-chiffre\">&gt; 90 %</span> des SEP — marqueur le plus utile</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Index IgG</strong></span></td><td>augmenté <span class=\"kw-chiffre\">&gt; 0,7</span> : traduit une synthèse intrathécale d'IgG</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Cytorachie</strong></span></td><td>lymphocytaire / plasmocytaire dans 1/3 des cas, entre <span class=\"kw-chiffre\">4 et 50 éléments/mm³</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Gammaglobulines</strong></span></td><td>élévation dans le <span class=\"kw-bio\">LCS</span> contrastant avec une concentration <span class=\"kw-clinique\">normale dans le sang</span> (≈ <span class=\"kw-chiffre\">70 %</span> des cas) — traduit la synthèse intrathécale</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Protéinorachie</strong></span></td><td><span class=\"kw-bio\">hyperprotéinorachie modérée &lt; 1 g/L</span> dans <span class=\"kw-chiffre\">25 %</span> des cas ; le <span class=\"kw-bio\">LCS</span> peut aussi être totalement <span class=\"kw-clinique\">normal</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Potentiels évoqués visuels (PEV)</strong> — de moins en moins pratiqués, mais ils restent les plus utilisés vu la fréquence de la névrite optique. Indications : <span class=\"kw-imagerie\">IRM</span> et <span class=\"kw-bio\">LCS</span> non concluants, ou doute sur l'organicité des troubles. Ils objectivent : un <span class=\"kw-clinique\">allongement des temps de latence (onde P100)</span>, des anomalies <span class=\"kw-clinique\">très altérées au stade aigu</span> y compris en l'absence de neuropathie optique clinique, et un <span class=\"kw-clinique\">ralentissement de conduction sur l'œil controlatéral sain</span> (argument de dissémination spatiale).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Il n'y a <span class=\"kw-alerte\">PAS de syndrome inflammatoire biologique</span> dans la SEP. Sa présence doit faire évoquer un différentiel : <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">Behçet</span>, <span class=\"kw-etio\">Gougerot-Sjögren</span>, <span class=\"kw-etio\">vascularite</span>.</div>","frequence":4},{"id":"104-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement d’une poussée de SEP","contenu":"<p>Le traitement de la poussée est <strong>distinct</strong> du traitement de fond (rang C, hors EDN, mentionné en obj-11). Il repose sur la <span class=\"kw-ttt\">corticothérapie à fortes doses</span>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Indication</strong></td><td><span class=\"kw-alerte\">non systématique</span> : discutée avec le patient si les symptômes sont gênants — elle ne modifie pas le <span class=\"kw-def\">pronostic</span> final</td></tr>\n          <tr><td><strong>Objectif</strong></td><td><span class=\"kw-clinique\">accélérer la récupération</span> de la poussée et <span class=\"kw-clinique\">retarder le 2<sup>e</sup> épisode</span> ; aucun effet sur la prévention de nouvelles poussées</td></tr>\n          <tr><td><strong>Molécule</strong></td><td><span class=\"kw-ttt\">méthylprednisolone</span> à fortes doses</td></tr>\n          <tr><td><strong>Schéma (CEN)</strong></td><td><span class=\"kw-chiffre\">3 jours</span>, par voie IV ou per os</td></tr>\n          <tr><td><strong>Schéma NORB (ONTT)</strong></td><td><span class=\"kw-ttt\">corticothérapie</span> parentérale en bolus, <span class=\"kw-ttt\">1 g/jour IV pendant 3 à 5 jours</span>, suivie parfois d'un relais oral court (<span class=\"kw-chiffre\">11 jours</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span>.</strong> Dans la NORB, la <span class=\"kw-ci\">corticothérapie orale seule est contre-indiquée</span> : elle expose à un risque accru de <span class=\"kw-alerte\">rechutes visuelles</span> (essai ONTT). Le traitement passe par la voie <span class=\"kw-ttt\">parentérale (IV)</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":4},{"id":"104-12","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications de la SEP","contenu":"<p>Les complications de la SEP sont nombreuses et relèvent d'une <span class=\"kw-def\">prise en charge symptomatique pluridisciplinaire</span>. L'objectif n'est pas la récupération complète mais le contrôle le plus durable possible du retentissement fonctionnel.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Évaluation et prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Spasticité</strong></span></td>\n            <td><strong>Évaluation :</strong> échelle d'<span class=\"kw-clinique\">Ashworth</span>, <span class=\"kw-clinique\">score de Penn</span><br><strong>PEC non médicamenteuse :</strong> kinésithérapie (étirements lents, postures d'inhibition ± orthèses), <span class=\"kw-ttt\">cryothérapie</span><br><strong>Local :</strong> injections de <span class=\"kw-ttt\">toxine botulique</span> dans les muscles hypertoniques ; <span class=\"kw-ttt\">chirurgie</span> (neurotomies sélectives, ténotomies)<br><strong>Général :</strong> <span class=\"kw-ttt\">baclofène</span> per os ou intrathécal (pompe), <span class=\"kw-ttt\">dantrolène</span> (action périphérique)<br><strong>Autres :</strong> <span class=\"kw-ttt\">benzodiazépines</span>, <span class=\"kw-ttt\">tizanidine</span> / <span class=\"kw-ttt\">clonidine</span> (α2-agonistes centraux), <span class=\"kw-ttt\">gabapentine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Déficiences neuro-motrices</strong></span></td>\n            <td><strong>Renforcement des contrôles moteurs :</strong> mobilisations actives aidées, rééducation neuromotrice, rééducation en position de fonction<br><strong>Réadaptation à l'effort :</strong> cardiovasculaire, musculaire, fonctionnelle</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Troubles de la marche</strong></span></td>\n            <td>atteinte la plus visible, au 1<sup>er</sup> plan de la gêne ; évaluation par le <span class=\"kw-clinique\">périmètre de marche</span>, l'<span class=\"kw-clinique\">EDSS</span> et le <span class=\"kw-clinique\">test de marche des 25 pieds (T25FW)</span> ; recours fréquent aux aides techniques</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Déficiences neuro-orthopédiques</strong></span></td>\n            <td><span class=\"kw-clinique\">rétractions capsulo-ligamentaires</span> et musculo-tendineuses ; étirements, postures, parfois <span class=\"kw-ttt\">chirurgie</span> d'allongement tendineux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Troubles urinaires</strong></span></td>\n            <td><strong>Évaluation :</strong> <span class=\"kw-bio\">bilan urodynamique</span> et radiologique souvent nécessaire<br><strong>Hyperactivité vésicale :</strong> <span class=\"kw-ttt\">anticholinergiques</span>, injections intravésicales de <span class=\"kw-ttt\">toxine botulinique</span><br><strong><span class=\"kw-clinique\">Dysurie</span> :</strong> <span class=\"kw-ttt\">alphabloquants</span><br><strong>Résidu post-mictionnel :</strong> <span class=\"kw-ttt\">autosondages intermittents</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Déficiences neuro-sensorielles</strong></span></td>\n            <td><strong>Troubles visuels :</strong> séquelles de NORB, troubles oculomoteurs, nystagmus → bilan et rééducation orthoptique<br><strong><span class=\"kw-clinique\">Syndrome vestibulaire</span> :</strong> kinésithérapie posturale et vestibulaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Fatigue</strong></span></td>\n            <td>fréquente ; fractionnement des activités, sommeil de qualité ; les antiasthéniques (amantadine, modafinil) sont peu efficaces</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Troubles de la déglutition</strong></span></td>\n            <td>adaptation des textures, posture en antéflexion, rééducation orthophonique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Troubles sexuels</strong></span></td>\n            <td>notamment de l'érection ; PEC médicamenteuse et <span class=\"kw-def\">suivi</span> sexologique / psychothérapique</td>\n          </tr>\n          <tr>\n            <td><strong>Aspect médico-social</strong></td>\n            <td>dossier MDPH (PCH aides humaines / techniques), adaptation du logement, de la scolarité ou de l'activité professionnelle</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Traitement de fond (rang C — pour mémoire).</strong> En cas de SEP avérée, un traitement de fond est instauré par le neurologue : <span class=\"kw-ttt\">immunomodulateurs</span> (interférons β, acétate de glatiramère) ou traitements de 2<sup>e</sup> ligne (<span class=\"kw-ttt\">natalizumab</span>, <span class=\"kw-ttt\">fingolimod</span>, <span class=\"kw-ttt\">ocrelizumab</span>). Il vise à réduire la fréquence des poussées et à ralentir la progression du handicap.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Les <span class=\"kw-alerte\">troubles urinaires</span> sont très tombables en QCM : retenir le trépied <span class=\"kw-clinique\">hyperactivité vésicale</span> (anticholinergiques) / <span class=\"kw-clinique\">dysurie</span> (alphabloquants) / <span class=\"kw-clinique\">résidu post-mictionnel</span> (autosondages). Un bilan urodynamique est souvent nécessaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 96 — Neuropathie périphérique · 101 — <span class=\"kw-clinique\">Paralysie faciale</span> · 125 — Trouble miction - incontinence urinaire · 135 — <span class=\"kw-ttt\">Antalgique</span></em></p>","frequence":6,"liens":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/immunomodulateurs","label":"Pharmacomedicale — Immunomodulateurs"}]},{"id":"104-13","rang":"B","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant une suspicion de SEP","contenu":"<p>L'imagerie du SNC est l'examen clé devant une suspicion de SEP. C'est l'<span class=\"kw-imagerie\">IRM</span> qui est l'<span class=\"kw-def\">examen de référence</span> — le <span class=\"kw-imagerie\">scanner</span> n'a <span class=\"kw-alerte\">aucune place</span>. Le détail morphologique des lésions est traité en obj-14.</p>\n      <table >\n        <thead><tr><th>Territoire exploré</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\"><strong>IRM encéphalique</strong></span></td><td><span class=\"kw-clinique\">systématique</span> devant toute <span class=\"kw-clinique\">suspicion de SEP</span> ; examen de référence (le <span class=\"kw-imagerie\">scanner</span> n'a aucune place ❌)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>IRM médullaire</strong></span></td><td>en complément <span class=\"kw-clinique\">si suspicion de myélite</span> — recherche d'une <span class=\"kw-radio\">lésion ovalaire</span> sur <span class=\"kw-chiffre\">&lt; 3 étages vertébraux</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>IRM des nerfs optiques</strong></span></td><td><span class=\"kw-imagerie\">séquences dédiées à l'orbite</span> <span class=\"kw-clinique\">si suspicion de neuropathie optique</span> — recherche d'un <span class=\"kw-radio\">hyperT2</span> du nerf, <span class=\"kw-radio\">rehaussé après gadolinium</span> si récent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-imagerie\">IRM</span> encéphalique toujours ; <span class=\"kw-imagerie\">IRM</span> médullaire et <span class=\"kw-imagerie\">IRM</span> des nerfs optiques guidées par la clinique. L'aspect détaillé des lésions est traité en obj-14.</div>","frequence":1},{"id":"104-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les critères diagnostiques de dissémination spatiale et temporelle","contenu":"<p>Les <span class=\"kw-def\">critères de McDonald 2017</span> opérationnalisent les deux disséminations nécessaires au diagnostic de SEP.</p>\n      <table >\n        <thead><tr><th>Dissémination</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Spatiale</strong></span></td>\n            <td><strong>Clinique :</strong> atteinte de plusieurs zones du SNC non expliquables par une <span class=\"kw-clinique\">lésion</span> unique<br><strong><span class=\"kw-imagerie\">IRM</span> :</strong> critère rempli si <span class=\"kw-chiffre\">≥ 1 lésion</span> dans <span class=\"kw-chiffre\">≥ 2 des 4 zones</span> stratégiques — <span class=\"kw-imagerie\">périventriculaire</span>, <span class=\"kw-imagerie\">juxta-corticale</span>, <span class=\"kw-imagerie\">sous-tentorielle</span>, <span class=\"kw-imagerie\">médullaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Temporelle</strong></span></td>\n            <td><strong>Forme progressive d'emblée :</strong> critère rempli si <span class=\"kw-clinique\">évolution</span> <span class=\"kw-chiffre\">&gt; 1 an</span><br><strong>Forme rémittente :</strong> succession d'épisodes (interrogatoire, clinique avec intervalle <span class=\"kw-chiffre\">≥ 1 mois</span>) ; ou <span class=\"kw-imagerie\">IRM</span> montrant de <span class=\"kw-radio\">nouvelles lésions</span> sur des examens successifs, ou l'association de <span class=\"kw-radio\">lésions prenant et ne prenant pas le gadolinium</span> sur une même <span class=\"kw-imagerie\">IRM</span><br><strong>Si critère temporel absent à l'<span class=\"kw-imagerie\">IRM</span> initiale :</strong> deux voies équivalentes — soit nouvelle <span class=\"kw-imagerie\">IRM de contrôle <span class=\"kw-chiffre\">~3 mois</span> après</span> l'<span class=\"kw-imagerie\">IRM</span> initiale, soit recherche de <span class=\"kw-bio\">bandes oligoclonales</span> au <span class=\"kw-bio\">LCS</span><br><strong>Substitut <span class=\"kw-bio\">LCS</span> :</strong> la présence de <span class=\"kw-bio\">bandes oligoclonales</span> peut remplacer le critère temporel (permet un diagnostic plus précoce)</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 380\" role=\"img\" aria-label=\"Arbre des critères de McDonald 2017 pour le diagnostic de sclérose en plaques. Première question, la dissémination spatiale : existe-t-il au moins une lésion dans au moins deux des quatre zones stratégiques (périventriculaire, juxta-corticale, sous-tentorielle, médullaire) ? Si non, le critère de dissémination spatiale n'est pas rempli et le diagnostic n'est pas retenu. Si oui, on évalue la dissémination temporelle : a-t-on des lésions d'âges différents, c'est-à-dire des lésions prenant et ne prenant pas le gadolinium sur la même IRM, ou une nouvelle lésion sur une IRM de contrôle, ou des bandes oligoclonales au LCS qui peuvent remplacer ce critère ? Si oui, le diagnostic de SEP est retenu. Si non, on contrôle par une nouvelle IRM à environ trois mois ou une ponction lombaire à la recherche de bandes oligoclonales.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\"><span class=\"kw-def\">Critères de</span> McDonald 2017 : DIS puis DIT</text>\n          <rect class=\"fb-blue\" x=\"120\" y=\"36\" width=\"320\" height=\"50\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Dissémination SPATIALE (DIS)</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"73\" text-anchor=\"middle\" font-size=\"10.5\">≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>ésion dans ≥ 2 des 4 zones stratégiques ?</text>\n          <line class=\"ln\" x1=\"280\" y1=\"86\" x2=\"280\" y2=\"102\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"150\" y1=\"102\" x2=\"410\" y2=\"102\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"150\" y1=\"102\" x2=\"150\" y2=\"118\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"150,124 145,116 155,116\"/>\n          <line class=\"ln\" x1=\"410\" y1=\"102\" x2=\"410\" y2=\"118\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"410,124 405,116 415,116\"/>\n          <text class=\"tx-muted\" x=\"160\" y=\"116\" font-size=\"10\" font-weight=\"600\">NON</text>\n          <text class=\"tx-muted\" x=\"420\" y=\"116\" font-size=\"10\" font-weight=\"600\">OUI</text>\n          <rect class=\"fb-red\" x=\"30\" y=\"126\" width=\"200\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"130\" y=\"146\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">DIS non remplie</text>\n          <text class=\"tx-red\" x=\"130\" y=\"162\" text-anchor=\"middle\" font-size=\"10.5\">diagnostic de SEP non retenu</text>\n          <rect class=\"fb-blue\" x=\"282\" y=\"126\" width=\"268\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"416\" y=\"146\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Dissémination TEMPORELLE (DIT)</text>\n          <text class=\"tx-blue\" x=\"416\" y=\"162\" text-anchor=\"middle\" font-size=\"9.5\">lésions d'âges différents (gado + / gado −),</text>\n          <text class=\"tx-blue\" x=\"416\" y=\"176\" text-anchor=\"middle\" font-size=\"9.5\">nouvelle <span class=\"kw-clinique\">lésion</span>, ou bandes oligoclonales ?</text>\n          <line class=\"ln\" x1=\"416\" y1=\"186\" x2=\"416\" y2=\"202\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"300\" y1=\"202\" x2=\"500\" y2=\"202\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"300\" y1=\"202\" x2=\"300\" y2=\"218\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"300,224 295,216 305,216\"/>\n          <line class=\"ln\" x1=\"500\" y1=\"202\" x2=\"500\" y2=\"218\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"500,224 495,216 505,216\"/>\n          <text class=\"tx-muted\" x=\"310\" y=\"216\" font-size=\"10\" font-weight=\"600\">NON</text>\n          <text class=\"tx-muted\" x=\"510\" y=\"216\" font-size=\"10\" font-weight=\"600\">OUI</text>\n          <rect class=\"fb-amber\" x=\"204\" y=\"226\" width=\"192\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"300\" y=\"246\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Contrôler</text>\n          <text class=\"tx-amber\" x=\"300\" y=\"263\" text-anchor=\"middle\" font-size=\"10\">nouvelle <span class=\"kw-imagerie\">IRM</span> à ~<span class=\"kw-chiffre\">3 mois</span></text>\n          <text class=\"tx-amber\" x=\"300\" y=\"277\" text-anchor=\"middle\" font-size=\"10\">OU PL : bandes oligoclonales</text>\n          <text class=\"tx-amber\" x=\"300\" y=\"291\" text-anchor=\"middle\" font-size=\"10\">(substitut du critère temporel)</text>\n          <rect class=\"fb-ok\" x=\"408\" y=\"226\" width=\"128\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"472\" y=\"256\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">SEP</text>\n          <text class=\"tx-ok\" x=\"472\" y=\"274\" text-anchor=\"middle\" font-size=\"10\">diagnostic</text>\n          <text class=\"tx-ok\" x=\"472\" y=\"288\" text-anchor=\"middle\" font-size=\"10\">retenu</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"328\" text-anchor=\"middle\" font-size=\"9.5\">4 zones DIS : périventriculaire · juxta-corticale · sous-tentorielle · médullaire</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"346\" text-anchor=\"middle\" font-size=\"9.5\">Forme progressive d'emblée : critère temporel rempli si évolution &gt;<span class=\"kw-chiffre\"> 1 an</span></text>\n        </svg>\n        <figcaption>Arbre McDonald 2017 : <span class=\"kw-def\">dissémination spatiale</span> (<span class=\"kw-chiffre\">≥ 1</span> lésion dans ≥ 2 des 4 zones) puis <span class=\"kw-def\">dissémination temporelle</span> (lésions d'âges différents / nouvelle lésion / <span class=\"kw-bio\">bandes oligoclonales</span>). Source : fiche source EDN item 104.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La dissémination spatiale répond à la question « plusieurs endroits ? » (≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>ésion dans ≥ 2 des 4 zones <span class=\"kw-imagerie\">IRM</span>). La dissémination temporelle répond à « plusieurs moments ? ». Les bandes oligoclonales permettent d'anticiper le critère temporel et donc un diagnostic plus précoce.</div>","frequence":4},{"id":"104-15","rang":"B","rubrique":"Contenu multimédia","titre":"IRM de SEP typique","contenu":"<p>L'<span class=\"kw-imagerie\">IRM</span> typique de SEP met en évidence des <span class=\"kw-imagerie\">plaques de démyélinisation</span> de la substance blanche, dont la <span class=\"kw-imagerie\">topographie</span> et le <span class=\"kw-imagerie\">signal</span> sont caractéristiques.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Aspect typique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\"><strong>Morphologie</strong></span></td><td>lésions <span class=\"kw-radio\">ovoïdes</span>, habituellement <span class=\"kw-chiffre\">&gt; 3 mm</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Signal</strong></span></td><td><span class=\"kw-radio\">hypersignal T2 / FLAIR</span> ; <span class=\"kw-radio\">hyposignal T1</span> inconstant (« trous noirs »)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Lésion récente</strong></span></td><td><span class=\"kw-radio\">rehaussement après injection de gadolinium en T1</span> si la <span class=\"kw-clinique\">lésion</span> date de <span class=\"kw-chiffre\">≤ 1 mois</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Périventriculaire</strong></span></td><td>localisation majoritaire ; <span class=\"kw-radio\">grand axe perpendiculaire</span> à l'axe des ventricules (« doigts de Dawson »)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Juxta-corticale</strong></span></td><td>au contact du cortex, <span class=\"kw-radio\">ne respectant pas les fibres en U</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Sous-tentorielle</strong></span></td><td><span class=\"kw-imagerie\">cervelet</span> et <span class=\"kw-imagerie\">tronc cérébral</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Médullaire</strong></span></td><td><span class=\"kw-clinique\">lésion</span> <span class=\"kw-radio\">ovalaire</span> sur <span class=\"kw-chiffre\">&lt; 3 étages vertébraux</span> et <span class=\"kw-chiffre\">&lt; 50 %</span> de la largeur de la moelle</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-typique-flair.png\" alt=\"IRM cérébrale FLAIR — multiples plaques de démyélinisation de la substance blanche au cours d'une SEP\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale, <span class=\"kw-imagerie\">séquence <span class=\"kw-imagerie\">FLAIR</span></span> : multiples plaques de démyélinisation de la substance blanche, en hypersignal — aspect typique de SEP. Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-flair-axial.png\" alt=\"IRM cérébrale FLAIR axiale — lésions de la substance blanche au cours d'une SEP\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale, coupe axiale <span class=\"kw-imagerie\">FLAIR</span> : lésions ovoïdes en hypersignal de la substance blanche. Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-doigts-dawson.png\" alt=\"IRM — lésions périventriculaires à grand axe perpendiculaire aux ventricules (doigts de Dawson)\" loading=\"lazy\">\n        <figcaption>Lésions périventriculaires à grand axe perpendiculaire à l'axe des ventricules — aspect en « doigts de Dawson ». Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-juxtacorticale.png\" alt=\"IRM — plaque de démyélinisation juxta-corticale au contact du cortex\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Plaque</span> de démyélinisation juxta-corticale, au contact du cortex, ne respectant pas les fibres en U. Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-sous-tentorielle.png\" alt=\"IRM — lésion sous-tentorielle (cervelet / tronc cérébral) au cours d'une SEP\" loading=\"lazy\">\n        <figcaption>Lésion sous-tentorielle (cervelet / tronc cérébral). Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/104/irm-sep-medullaire.png\" alt=\"IRM médullaire — lésion ovalaire sur moins de 3 étages vertébraux au cours d'une SEP\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> médullaire : lésion ovalaire sur moins de 3 étages vertébraux et moins de <span class=\"kw-chiffre\">50 %</span> de la largeur de la moelle. Source : fiche source EDN item 104 — Sclérose en plaques.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> 4 zones stratégiques (<span class=\"kw-imagerie\">périventriculaire</span>, <span class=\"kw-imagerie\">juxta-corticale</span>, <span class=\"kw-imagerie\">sous-tentorielle</span>, <span class=\"kw-imagerie\">médullaire</span>) ; lésions <span class=\"kw-imagerie\">ovoïdes &gt; 3 mm</span> en hypersignal T2/<span class=\"kw-imagerie\">FLAIR</span> ; le <span class=\"kw-radio\">rehaussement gadolinium</span> signe une <span class=\"kw-clinique\">lésion</span> récente (<span class=\"kw-chiffre\">≤ 1 mois</span>).</div>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/multiple-sclerosis","label":"Radiopaedia : Multiple sclerosis"}]},{"id":"104-16","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes ophtalmologiques d’atteinte de la SEP : neuropathie optique, paralysies oculo-motrices, nystagmus","contenu":"<p>Les atteintes oculaires sont fréquentes et souvent révélatrices. Le <span class=\"kw-def\">terrain</span> est celui de la SEP : adulte jeune (<span class=\"kw-chiffre\">20-40 ans</span>), prédominance féminine (<span class=\"kw-chiffre\">75 %</span>).</p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Neuropathie optique (NORB)</strong></span></td><td>manifestation ophtalmologique la plus fréquente, <span class=\"kw-clinique\">inaugurale dans 20-25 %</span> des cas ; neuropathie optique <span class=\"kw-etio\">inflammatoire</span> démyélinisante (détaillée en obj-3)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Paralysies oculomotrices</strong></span></td><td><span class=\"kw-clinique\">paralysie du VI</span> ; <span class=\"kw-clinique\">ophtalmoplégie internucléaire</span> (atteinte du faisceau longitudinal médian) ; atteinte <span class=\"kw-clinique\">supranucléaire</span> (<span class=\"kw-clinique\">syndrome de Parinaud</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Nystagmus</strong></span></td><td><span class=\"kw-clinique\">pendulaire</span> ou <span class=\"kw-clinique\">à ressort</span> ; responsable d'<span class=\"kw-clinique\">oscillopsies</span> ou d'une baisse d'acuité visuelle par instabilité de la fixation du regard</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Périphlébites rétiniennes</strong></span></td><td><span class=\"kw-radio\">engainements blanchâtres</span> des veines rétiniennes périphériques</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Trio classique : <span class=\"kw-def\">neuropathie optique</span> (NORB), <span class=\"kw-def\">paralysies oculomotrices</span> (dont l'ophtalmoplégie internucléaire, très évocatrice chez un sujet jeune) et <span class=\"kw-def\">nystagmus</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":1},{"id":"104-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan ophtalmologique d’une NORB : acuité visuelle, champ visuel, PEV","contenu":"<p>Le diagnostic de NORB est <span class=\"kw-def\">clinique</span> ; le bilan ophtalmologique le confirme et en précise la sévérité.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Résultat dans la NORB</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Acuité visuelle</strong></span></td><td>baisse unilatérale d'importance variable, souvent marquée (peut être &lt; 1/10)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Champ visuel</strong></span></td><td>la <span class=\"kw-clinique\">périmétrie statique</span> est la plus adaptée : <span class=\"kw-clinique\">scotome central ou cæcocentral</span> du côté atteint</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Vision des couleurs</strong></span></td><td>test de <span class=\"kw-clinique\">Farnsworth</span> : <span class=\"kw-clinique\">dyschromatopsie d'axe rouge-vert</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>OCT</strong></span></td><td>à la phase <span class=\"kw-clinique\">aiguë</span> : épaississement possible des fibres ganglionnaires péripapillaires ; au <span class=\"kw-def\">stade</span> <span class=\"kw-clinique\">séquellaire</span> : perte d'épaisseur évoluant vers une <span class=\"kw-alerte\">atrophie optique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>PEV</strong></span></td><td><span class=\"kw-clinique\">allongement de la latence (onde P100)</span> ; anomalies très altérées au <span class=\"kw-def\">stade</span> aigu, possiblement <span class=\"kw-clinique\">bilatérales</span> (atteinte infraclinique de l'œil controlatéral)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Trépied du bilan : <span class=\"kw-clinique\">acuité visuelle</span> + <span class=\"kw-clinique\">champ visuel</span> (scotome central/cæcocentral) + <span class=\"kw-clinique\">PEV</span> (allongement P100). L'<span class=\"kw-imagerie\">OCT</span> complète l'évaluation, surtout au <span class=\"kw-def\">stade</span> séquellaire.</div>","frequence":1},{"id":"104-18","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","contenu":"<p>La <span class=\"kw-etio\">NORB</span> engage le <span class=\"kw-alerte\">pronostic visuel</span> de l'œil atteint : elle constitue une <span class=\"kw-alerte\">urgence diagnostique</span> chez l'<span class=\"kw-clinique\">adulte jeune</span>.</p>\n      <p>Toute baisse d'acuité visuelle <span class=\"kw-clinique\">unilatérale</span>, <span class=\"kw-clinique\">subaiguë</span> (heures à jours) et <span class=\"kw-clinique\">douloureuse</span> aux mouvements oculaires chez l'adulte jeune impose un <span class=\"kw-clinique\">examen ophtalmologique</span> et neurologique sans délai, afin de confirmer le diagnostic, d'éliminer les <span class=\"kw-etio\">diagnostics différentiels</span> (voir obj-19) et d'instaurer rapidement le <span class=\"kw-ttt\">traitement de la poussée</span> si besoin.</p>\n      <table >\n        <thead><tr><th>Décision</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Confirmer la NORB</strong></td><td>bilan ophtalmologique (AV, CV, <span class=\"kw-imagerie\">FO</span>, <span class=\"kw-clinique\">Farnsworth</span>) ; <span class=\"kw-imagerie\">IRM encéphalique + nerfs optiques</span> ; ± <span class=\"kw-bio\">PL</span></td></tr>\n          <tr><td><strong>Repérer un piège</strong></td><td>NORB <span class=\"kw-alerte\">bilatérale</span>, profonde ou atypique → suspecter une <span class=\"kw-etio\">neuromyélite de Devic</span> (anti-<span class=\"kw-bio\">AQP4</span> / anti-<span class=\"kw-bio\">MOG</span>)</td></tr>\n          <tr><td><strong>Traiter</strong></td><td><span class=\"kw-ttt\">méthylprednisolone IV 1 g/j × 3-5 j</span> ; <span class=\"kw-ci\">corticothérapie orale seule contre-indiquée</span> (rechutes visuelles)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une NORB <span class=\"kw-alerte\">menace</span> le <span class=\"kw-def\">pronostic</span> visuel et est une urgence diagnostique : ne pas différer le bilan ophtalmologique et neurologique. Une NORB grave, bilatérale ou atypique doit faire évoquer une <span class=\"kw-etio\">neuromyélite de Devic</span>, dont la prise en charge est très différente.</div>","frequence":0},{"id":"104-19","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le potentiel évolutif d’une NORB","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> d'une NORB est <strong>globalement favorable</strong>, mais elle expose à un risque d'évolution vers une SEP.</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Évolution</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Récupération visuelle</strong></td><td>spontanée dans <span class=\"kw-chiffre\">&gt; 90 %</span> des cas, en <span class=\"kw-chiffre\">3 à 6 mois</span> ; après un 1<sup>er</sup> épisode, la grande majorité retrouve une AV normale mais des troubles des contrastes ou des couleurs persistent parfois ; l'<span class=\"kw-clinique\">acuité visuelle initiale</span> est le meilleur facteur prédictif de l'acuité finale</td></tr>\n          <tr>\n            <td><strong>Risque d'<span class=\"kw-clinique\">évolution</span> vers une SEP</strong></td>\n            <td>risque global de <span class=\"kw-chiffre\">50 % à 15 ans</span> ; réduit à <span class=\"kw-chiffre\">25 %</span> si l'<span class=\"kw-imagerie\">IRM initiale est normale</span> ; porté à <span class=\"kw-chiffre\">75 %</span> si <span class=\"kw-imagerie\">≥ 1 lésion encéphalique</span> à l'<span class=\"kw-imagerie\">IRM</span></td>\n          </tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Phénomène d'Uhthoff</strong></span></td><td><span class=\"kw-clinique\">baisse d'acuité visuelle transitoire et réversible</span> (flou visuel de quelques <span class=\"kw-chiffre\">minutes</span>) lors d'une <span class=\"kw-clinique\">élévation de la température corporelle</span> (effort physique, bain chaud, <span class=\"kw-clinique\">fièvre</span>) — traduit la <span class=\"kw-def\">thermolabilité des axones démyélinisés</span> ; <span class=\"kw-alerte\">ce n'est pas une poussée</span> et ne justifie <span class=\"kw-ci\">pas de corticothérapie</span></td></tr>\n          <tr><td><strong>Récidive</strong></td><td>homo- ou controlatérale, chez <span class=\"kw-chiffre\">30 %</span> des patients</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-alerte\">phénomène d'Uhthoff</span> (flou visuel transitoire à la chaleur ou à l'effort) est une <span class=\"kw-alerte\">pseudo-poussée</span> : il ne compte pas comme une poussée et ne justifie pas de <span class=\"kw-ttt\">corticothérapie</span>. L'<span class=\"kw-imagerie\">IRM</span> initiale stratifie le risque d'<span class=\"kw-clinique\">évolution</span> vers une SEP (<span class=\"kw-chiffre\">25 %</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">75 %</span>).</div>","frequence":0},{"id":"104-20","rang":"B","rubrique":"Diagnostic positif","titre":"Distinguer une NORB d’une autre atteinte de baisse de l’acuité visuelle à fond d’œil normal","contenu":"<p>Devant une baisse d'acuité visuelle à <span class=\"kw-clinique\">fond d'œil normal</span>, la NORB liée à la SEP n'est qu'une étiologie parmi d'autres neuropathies optiques. Le <span class=\"kw-def\">diagnostic différentiel</span> est essentiel car la prise en charge diffère.</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Toxique</span> / iatrogène / traumatique</strong></td><td><span class=\"kw-etio\">éthambutol</span> (antituberculeux) ; autres causes toxiques ; <span class=\"kw-etio\">traumatique</span> (contusion ou <span class=\"kw-clinique\">lésion</span> directe du nerf optique) ; idiopathique</td></tr>\n          <tr><td><strong>Compression</strong></td><td><span class=\"kw-etio\">anévrisme de la carotide interne</span> ; <span class=\"kw-etio\">méningiome</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Neuromyélite de Devic</strong></span></td><td>DD principal de la SEP : névrite optique plus sévère (installation <span class=\"kw-clinique\">rapide</span>, souvent <span class=\"kw-clinique\">bilatérale</span> ou à bascule, <span class=\"kw-clinique\">BAV profonde</span>) ; auto-anticorps anti-<span class=\"kw-bio\">AQP4</span> ou anti-<span class=\"kw-bio\">MOG</span></td></tr>\n          <tr><td><strong>Neuropathies optiques non démyélinisantes</strong></td><td><strong>Maladies systémiques :</strong> <span class=\"kw-etio\">LED</span>, <span class=\"kw-etio\">panartérite noueuse</span>, <span class=\"kw-etio\">maladie de Behçet</span>, <span class=\"kw-etio\">sarcoïdose</span><br><strong>Infections :</strong> <span class=\"kw-etio\">maladie de Lyme</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">herpèsvirus</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Une névrite optique <span class=\"kw-alerte\">bilatérale, profonde ou atypique</span> doit faire évoquer une <span class=\"kw-etio\">neuromyélite de Devic</span> (anti-AQP4 / anti-MOG) plutôt qu'une SEP : son <span class=\"kw-def\">pronostic</span> est plus réservé et les immunomodulateurs y sont <span class=\"kw-ci\">contre-indiqués</span>.</div>","frequence":0}],"astuces":[{"type":"tip","titre":"Phénomène d'Uhthoff = réchauffement","contenu":"La chaleur (bain chaud, effort physique, fièvre) aggrave transitoirement les symptômes de SEP (vision trouble, fatigue, paresthésies). Ce n'est PAS une poussée, c'est un phénomène réversible de blocage de conduction dans les fibres démyélinisées."},{"type":"warn","titre":"NORB bilatérale = NMO avant SEP","contenu":"Devant une atteinte bilatérale des nerfs optiques, penser en priorité à la Neuromyélite optique (NMO/Devic) ou au MOGAD : rechercher les anticorps anti-Aquaporine-4 et anti-MOG avant de poser le diagnostic de SEP classique."},{"type":"danger","titre":"Solumédrol 1 g/j x 3j = schéma canonique","contenu":"Le traitement d'une poussée SEP est le Solumédrol 1 g/j IV pendant 3 jours. Pas de décroissance nécessaire. En cas de corticorésistance, passer à la plasmaférèse en urgence."},{"type":"info","titre":"Black holes T1 = mauvais pronostic","contenu":"Sur l'IRM, les hypo-signal T1 (black holes) correspondent à la destruction axonale irréversible. Leur nombre est un marqueur pronostique indépendant du risque de progression vers le handicap."}],"strategie":{"urgence":"<p><strong>NORB <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> diagnostique</span></strong></p><p>diagnostic <span class=\"kw-clinique\">clinique</span> + <span class=\"kw-bio\">bilan ophtalmologique</span> (<span class=\"kw-imagerie\">FO</span> le plus souvent normal, CV, vision des couleurs)</p><ul><li>La <span class=\"kw-def\">névrite optique rétrobulbaire</span> <span class=\"kw-alerte\">menace le pronostic visuel</span> : <span class=\"kw-alerte\">urgence</span> diagnostique</li><li><span class=\"kw-clinique\">BAV</span> rapidement progressive (<span class=\"kw-chiffre\">quelques heures à jours</span>), <em>jamais brutale</em>, le plus souvent <span class=\"kw-clinique\">unilatérale</span></li><li><span class=\"kw-clinique\">Douleurs rétro-oculaires</span> majorées aux <span class=\"kw-clinique\">mouvements oculaires</span> (<span class=\"kw-chiffre\">80 %</span>), mais œil <span class=\"kw-clinique\">blanc et indolore</span></li></ul><p><strong>Poussée de SEP <span class=\"q\">— traitement (rang A)</span></strong></p><p>accélère la récupération mais <span class=\"kw-alerte\">ne modifie pas le pronostic visuel final</span> : non systématique, discuté avec le patient</p><ul><li><span class=\"kw-ttt\">Méthylprednisolone</span> à <span class=\"kw-chiffre\">fortes doses</span> : <span class=\"kw-chiffre\">3 jours</span> IV ou per os (CEN)</li><li>NORB (ONTT) : bolus <span class=\"kw-ttt\">IV</span> <span class=\"kw-chiffre\">1 g/jour</span> pendant <span class=\"kw-chiffre\">3 à 5 jours</span> ± relais oral court (<span class=\"kw-chiffre\">11 jours</span>)</li><li><span class=\"kw-ci\">Corticothérapie orale seule contre-indiquée</span> dans la NORB (risque accru de rechutes visuelles)</li></ul><p><strong>Devic <span class=\"q\">— NORB grave / bilatérale / atypique</span></strong></p><p><span class=\"kw-ttt\">plasmaphérèse</span> + <span class=\"kw-ttt\">corticothérapie IV</span></p><ul><li>Évoquer une <span class=\"kw-etio\">neuromyélite de Devic</span> (anti-<span class=\"kw-bio\">AQP4</span> / anti-<span class=\"kw-bio\">MOG</span>) : <span class=\"kw-def\">pronostic</span> plus réservé, peut engager le <span class=\"kw-alerte\">pronostic vital</span></li><li><span class=\"kw-def\">Diagnostic précoce</span> indispensable (<span class=\"kw-ci\">immunomodulateurs contre-indiqués</span>)</li></ul>","hospit":"<p><strong><span class=\"kw-def\">Suivi</span> spécialisé :</strong> le <span class=\"kw-ttt\">traitement de fond</span> est instauré et suivi par le <span class=\"kw-def\">neurologue</span> en cas de SEP avérée.<br><strong>Milieu hospitalier spécialisé :</strong> instauration de certains traitements de fond — <span class=\"kw-ttt\">natalizumab</span> (perfusions mensuelles), <span class=\"kw-ttt\">fingolimod</span> (1ʳᵉ prise sous <span class=\"kw-clinique\">monitoring cardiaque</span>), <span class=\"kw-ttt\">mitoxantrone</span> (cures IV).<br><strong>Rééducation en libéral :</strong> à privilégier initialement (<span class=\"kw-ttt\">kinésithérapie</span> ambulatoire <span class=\"kw-chiffre\">1-2×/semaine</span>), débutée le plus tôt possible.<br><strong>Structure de rééducation :</strong> à proposer si <span class=\"kw-alerte\">majoration des incapacités</span> et dégradation fonctionnelle.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Altération de l’état général</span> → faire rechercher un <span class=\"kw-def\">diagnostic différentiel</span></li><li><span class=\"kw-alerte\">Atteinte d’un autre organe que le SNC</span> (interrogatoire / examen clinique général)</li><li><span class=\"kw-alerte\">Syndrome inflammatoire biologique</span> dans le sang : <em>il n’y a pas de <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> dans la SEP</em> → évoquer <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">Behçet</span>, <span class=\"kw-etio\">Gougerot-Sjögren</span>, <span class=\"kw-etio\">vascularite</span></li><li><span class=\"kw-alerte\">Méningite</span> et/ou <span class=\"kw-alerte\">absence de bandes oligoclonales</span> à l’examen du <span class=\"kw-bio\">LCS</span></li><li>Symptômes excluant quasiment la SEP : <span class=\"kw-clinique\">HLH</span>, <span class=\"kw-clinique\">cécité</span>, <span class=\"kw-clinique\">surdité</span>, atteinte du <span class=\"kw-clinique\">SNP</span>, <span class=\"kw-clinique\">syndrome extrapyramidal</span>, <span class=\"kw-clinique\">aphasie</span>, <span class=\"kw-clinique\">apraxie</span></li><li>NORB <span class=\"kw-alerte\">bilatérale, profonde ou atypique</span> → <span class=\"kw-etio\">neuromyélite de Devic</span> (anti-AQP4 / anti-MOG)</li></ul>","principes":"<p><strong>Règle d’or :</strong> le <span class=\"kw-ttt\">traitement de la poussée</span> n’est <span class=\"kw-alerte\">pas systématique</span> et ne modifie pas le <span class=\"kw-def\">pronostic</span> final ; le <span class=\"kw-ttt\">traitement de fond</span> vise à <span class=\"kw-clinique\">réduire la fréquence des poussées</span> et <span class=\"kw-clinique\">ralentir la progression du handicap</span>.</p><p><strong>Traitement de la poussée <span class=\"q\">(rang A)</span></strong></p><ul><li><span class=\"kw-ttt\">Méthylprednisolone</span> <span class=\"kw-chiffre\">fortes doses</span>, <span class=\"kw-chiffre\">3 j</span> IV ou per os ; NORB : bolus IV <span class=\"kw-chiffre\">1 g/j</span> sur <span class=\"kw-chiffre\">3-5 j</span></li><li>Indication discutée (effets indésirables) ; accélère la récupération sans modifier le <span class=\"kw-def\">pronostic</span></li></ul><p><strong>Traitement de fond — 1ʳᵉ ligne <span class=\"q\">(forme active, rang C)</span></strong></p><ul><li><span class=\"kw-ttt\">Interférons β</span>, <span class=\"kw-ttt\">acétate de glatiramère</span>, <span class=\"kw-ttt\">diméthylfumarate</span>, <span class=\"kw-ttt\">tériflunomide</span>, <span class=\"kw-ttt\">ocrelizumab</span></li><li>Réduisent la fréquence des poussées de <span class=\"kw-chiffre\">30 à 50 %</span></li></ul><p><strong>Traitement de fond — 2ᵉ ligne <span class=\"q\">(maladie très active / échec, rang C)</span></strong></p><ul><li><span class=\"kw-ttt\">Natalizumab</span>, <span class=\"kw-ttt\">fingolimod</span>, <span class=\"kw-ttt\">mitoxantrone</span>, <span class=\"kw-ttt\">alemtuzumab</span>, <span class=\"kw-ttt\">cladribine</span>, <span class=\"kw-ttt\">ocrelizumab</span></li><li>Réduisent la fréquence des poussées de <span class=\"kw-chiffre\">50 à 70 %</span> ; <span class=\"kw-ttt\">ocrelizumab</span> = seul actif sur la forme primitivement progressive</li></ul><p><strong>Neuromyélite de Devic <span class=\"q\">— à ne pas traiter comme une SEP</span></strong></p><ul><li><span class=\"kw-ci\">Immunomodulateurs contre-indiqués</span></li><li><span class=\"kw-ttt\">Corticothérapie parentérale</span> + relais oral prolongé ± <span class=\"kw-ttt\">immunosuppresseur</span> (<span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">rituximab</span>, <span class=\"kw-ttt\">mycophénolate</span>)</li></ul><p><strong>Traitements symptomatiques</strong></p><ul><li>Spasticité : <span class=\"kw-ttt\">kinésithérapie</span>, <span class=\"kw-ttt\">baclofène</span>, <span class=\"kw-ttt\">dantrolène</span>, <span class=\"kw-ttt\">toxine botulique</span></li><li>Troubles urinaires : <span class=\"kw-ttt\">anticholinergiques</span> (hyperactivité vésicale), <span class=\"kw-ttt\">alphabloquants</span> (dysurie), <span class=\"kw-ttt\">autosondages</span> (résidu post-mictionnel)</li><li>Fatigue, douleurs, troubles de la marche : <span class=\"kw-ttt\">rééducation</span> multidisciplinaire précoce + aides techniques</li></ul>","suivi":"<p><strong>Modes évolutifs :</strong> <span class=\"kw-def\">forme rémittente-récurrente</span> (<span class=\"kw-chiffre\">85 %</span> des débuts) → <span class=\"kw-def\">secondairement progressive</span> (<span class=\"kw-chiffre\">15-20 ans après</span>) ; <span class=\"kw-def\">forme primaire progressive</span> (<span class=\"kw-chiffre\">15 %</span>, début vers <span class=\"kw-chiffre\">40 ans</span>).<br><strong>Maladie active :</strong> <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-clinique\">poussée</span> ou activité <span class=\"kw-imagerie\">radiologique</span> (nouvelles lésions T2 / lésions rehaussées par le gadolinium) au cours de l’année précédente.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> imprévisible et variable, <span class=\"kw-clinique\">espérance de vie peu réduite</span> ; mauvais pronostic si début <span class=\"kw-chiffre\">&gt; 40 ans</span>, forme <span class=\"kw-clinique\">primitivement progressive</span>, atteinte motrice initiale, charge lésionnelle <span class=\"kw-imagerie\">IRM</span> élevée.<br><strong>NORB → SEP :</strong> risque de conversion <span class=\"kw-chiffre\">50 % à 15 ans</span> (<span class=\"kw-chiffre\">25 %</span> si <span class=\"kw-imagerie\">IRM</span> initiale normale, <span class=\"kw-chiffre\">75 %</span> si ≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>ésion encéphalique) ; phénomène d’<span class=\"kw-def\">Uhthoff</span> ; récidive <span class=\"kw-chiffre\">30 %</span>.<br><strong><span class=\"kw-ci\">Grossesse</span> :</strong> grossesse normale ; le <span class=\"kw-clinique\">risque de poussées diminue</span> pendant la grossesse, mais <span class=\"kw-chiffre\">15-20 %</span> de poussées au 1ᵉ trimestre du post-partum ; traitements à discuter avant la conception ; <span class=\"kw-ci\">allaitement</span> possible selon les médicaments.<br><strong>Vaccins :</strong> pas de <span class=\"kw-ci\">contre-indication</span> liée à la SEP (y compris hépatite B) ; <span class=\"kw-ci\">vaccins vivants atténués contre-indiqués</span> sous <span class=\"kw-ttt\">immunosuppresseur</span> ; mettre à jour dès le diagnostic, avant le traitement de fond.</p><p><strong><span class=\"kw-def\">Surveillance</span> spécifique des traitements de fond</strong></p><ul><li><span class=\"kw-ttt\">Natalizumab</span> : risque de <span class=\"kw-alerte\">LEMP</span> (virus JC) → <span class=\"kw-bio\">sérologie JC</span>, exposition &gt;<span class=\"kw-chiffre\"> 2 ans</span>, <span class=\"kw-ttt\">immunosuppresseur</span> antérieur</li><li><span class=\"kw-ttt\">Fingolimod</span> : <span class=\"kw-alerte\">troubles de conduction cardiaque</span> à l’instauration, <span class=\"kw-clinique\">œdème maculaire</span></li><li><span class=\"kw-ttt\">Mitoxantrone</span> : <span class=\"kw-alerte\">toxicité cardiaque</span> + risque de <span class=\"kw-alerte\">LAM</span> → <span class=\"kw-def\">surveillance</span> cardio + hémato</li><li><span class=\"kw-ttt\">Diméthylfumarate</span> : <span class=\"kw-bio\">lymphopénie</span> prolongée → risque de <span class=\"kw-alerte\">LEMP</span></li><li><span class=\"kw-ttt\">Alemtuzumab</span> : <span class=\"kw-etio\">maladies auto-immunes</span> à<span class=\"kw-chiffre\"> 2-3 ans</span> (Basedow, hypothyroïdie, Goodpasture, thrombopénie)</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/sclerose-en-plaques","label":"Collège CEN — Sclérose en plaques"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tableau évocateur de SEP — Pas de drapeau rouge, pas de meilleure explication (diagnostics différentiels exclus)","detail":"<h4><span class=\"kw-def\">Critères de</span> McDonald 2017 — <span class=\"kw-def\">diagnostic positif</span> de SEP — Après exclusion des diagnostics différentiels</h4>","branches":[{"to":"t-no-dis","label":"Dissémination spatiale absente (< 2 zones du SNC atteintes)","color":"blue"},{"to":"q-dit","label":"Dissémination spatiale présente (≥ 1 lésion dans ≥ 2 des 4 zones, ou clinique multifocale)","color":"blue"}]},{"id":"t-no-dis","kind":"terminal","label":"SEP non retenue à ce stade","color":"blue","detail":"<h4>Interprétation</h4><ul><li>Une seule localisation : les <span class=\"kw-def\">critères de</span> <span class=\"kw-def\">McDonald 2017</span> ne sont pas remplis (syndrome cliniquement isolé).</li></ul><h4>CAT</h4><ul><li>Rechercher activement un <span class=\"kw-etio\">diagnostic différentiel</span> : névrite optique idiopathique, <span class=\"kw-etio\">neuromyélite de Devic</span> (anti-AQP4/MOG), <span class=\"kw-etio\">tumeur</span> / <span class=\"kw-etio\">compression médullaire</span>, <span class=\"kw-etio\">sarcoïdose</span> · <span class=\"kw-etio\">Behçet</span> · <span class=\"kw-etio\">lupus</span> · <span class=\"kw-etio\">Gougerot-Sjögren</span></li><li><span class=\"kw-clinique\">Surveillance</span> clinique et nouvelle évaluation en cas de nouvel épisode</li></ul>"},{"id":"q-dit","kind":"decision","label":"Dissémination temporelle démontrée ? — Lésions d’âges différents · 2ᵉ poussée · nouvelle lésion sur IRM successive · lésions prenant ET ne prenant pas le gadolinium · bandes oligoclonales au LCS","branches":[{"to":"t-sep","label":"Oui","color":"blue"},{"to":"t-controle","label":"Non","color":"amber"}]},{"id":"t-sep","kind":"terminal","label":"SEP retenue","color":"blue","detail":"<h4>Critères</h4><ul><li><span class=\"kw-def\">Dissémination spatiale</span> + <span class=\"kw-def\">dissémination temporelle</span> remplies, en l’absence de meilleure explication.</li></ul><h4>À noter</h4><ul><li>Diagnostic possible <span class=\"kw-chiffre\">dès la 1ʳᵉ poussée</span> si la dissémination temporelle est présente d’emblée (lésions d’âges différents).</li></ul><h4>PEC</h4><ul><li><span class=\"kw-def\">Annonce</span> diagnostique ; <span class=\"kw-ttt\">traitement de fond</span> instauré par le <span class=\"kw-def\">neurologue</span> si forme active</li><li><span class=\"kw-ttt\">Méthylprednisolone</span> en cas de poussée invalidante</li></ul>"},{"id":"t-controle","kind":"terminal","label":"Critère temporel à compléter","color":"amber","detail":"<h4>Situation</h4><ul><li>Dissémination spatiale présente, mais <span class=\"kw-def\">dissémination temporelle</span> non encore démontrée.</li></ul><h4>CAT — 2 options</h4><ul><li>Nouvelle <span class=\"kw-imagerie\">IRM cérébrale à ~3 mois</span> de l’<span class=\"kw-imagerie\">IRM</span> initiale (recherche de nouvelles lésions, ou de lésions prenant et ne prenant pas le contraste)</li><li><span class=\"kw-bio\">Ponction lombaire</span> : la présence de <span class=\"kw-bio\">bandes oligoclonales</span> remplace le <span class=\"kw-def\">critère de</span> dissémination temporelle (diagnostic plus précoce)</li></ul>"}]},"cards":[{"i":"386c53ad0a6c","n":104,"o":"104-16","u":"Diagnostic positif","t":"Connaître les signes ophtalmologiques d’atteinte de la SEP : neuropathie optique, paralysies oculo-motrices, nystagmus","q":"Quelles sont les principales formes de paralysies oculo-motrices observées dans la Sclérose en Plaques ?","a":"<p>Les principales formes de paralysies oculo-motrices observées dans la Sclérose en Plaques sont :</p><ul><li>La <strong>paralysie du VI</strong> (nerf abducens).</li><li>L'<strong>ophtalmoplégie internucléaire</strong> (due à une atteinte du faisceau longitudinal médian), très évocatrice chez un sujet jeune.</li><li>Les atteintes supranucléaires, comme le <strong>syndrome de Parinaud</strong>.</li></ul>"},{"i":"3e76e88d53b3","n":104,"o":"104-16","u":"Diagnostic positif","t":"Connaître les signes ophtalmologiques d’atteinte de la SEP : neuropathie optique, paralysies oculo-motrices, nystagmus","q":"Quelle est la neuropathie optique la plus fréquente associée à la Sclérose en Plaques ?","a":"<p>La neuropathie optique la plus fréquente dans la Sclérose en Plaques est la <strong>neuropathie optique rétrobulbaire (NORB)</strong>. Elle est inaugurale dans <strong>20 à 25 %</strong> des cas.</p>"},{"i":"51bc76a38796","n":104,"o":"104-16","u":"Diagnostic positif","t":"Connaître les signes ophtalmologiques d’atteinte de la SEP : neuropathie optique, paralysies oculo-motrices, nystagmus","q":"Comment se manifeste le nystagmus dans la Sclérose en Plaques et quelles en sont les conséquences cliniques ?","a":"<p>Le nystagmus dans la Sclérose en Plaques peut être <strong>pendulaire ou à ressort</strong>. Il est responsable d'<strong>oscillopsies</strong> (sensation de mouvement des objets fixes) ou d'une <strong>baisse d'acuité visuelle</strong> par instabilité de la fixation du regard.</p>"},{"i":"9e26a4976ced","n":104,"o":"104-16","u":"Diagnostic positif","t":"Connaître les signes ophtalmologiques d’atteinte de la SEP : neuropathie optique, paralysies oculo-motrices, nystagmus","q":"Quel est le trio classique des signes ophtalmologiques évocateurs de la Sclérose en Plaques ?","a":"<p>Le trio classique des signes ophtalmologiques évocateurs de la Sclérose en Plaques comprend :</p><ul><li>La <strong>neuropathie optique (NORB)</strong>.</li><li>Les <strong>paralysies oculomotrices</strong>, notamment l'<strong>ophtalmoplégie internucléaire</strong>.</li><li>Le <strong>nystagmus</strong>.</li></ul>"},{"i":"45b8a3b6af0c","n":104,"o":"104-18","u":"Identifier une urgence","t":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","q":"Pourquoi la névrite optique rétrobulbaire (NORB) est-elle considérée comme une urgence diagnostique chez l'adulte jeune ?","a":"<p>La NORB est une urgence diagnostique chez l'adulte jeune car elle peut <strong>engager le pronostic visuel de l'œil atteint</strong>. Un diagnostic rapide est crucial pour éliminer les diagnostics différentiels et instaurer le traitement si nécessaire.</p>"},{"i":"5a3d5c43f342","n":104,"o":"104-18","u":"Identifier une urgence","t":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","q":"Quel bilan diagnostique doit être réalisé en urgence devant une suspicion de névrite optique rétrobulbaire (NORB) chez l'adulte jeune ?","a":"<ul><li>Un <strong>examen ophtalmologique</strong> complet (acuité visuelle, champ visuel, fond d'œil, test de Farnsworth).</li><li>Une <strong>IRM encéphalique</strong> avec séquences spécifiques des nerfs optiques.</li><li>Éventuellement, une <strong>ponction lombaire</strong>.</li></ul>"},{"i":"a0cb793cfbc0","n":104,"o":"104-18","u":"Identifier une urgence","t":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","q":"Quels sont les pièges diagnostiques à considérer en cas de névrite optique rétrobulbaire (NORB) atypique ?","a":"<p>Une NORB <strong>bilatérale, profonde ou atypique</strong> doit faire suspecter une <strong>neuromyélite optique (maladie de Devic)</strong>. Le diagnostic est alors orienté par la recherche d'anticorps <strong>anti-AQP4</strong> ou <strong>anti-MOG</strong>, car la prise en charge thérapeutique est très différente.</p>"},{"i":"b6518ba69e01","n":104,"o":"104-18","u":"Identifier une urgence","t":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","q":"Quelle est la prise en charge thérapeutique de la névrite optique rétrobulbaire (NORB) ?","a":"<p>Le traitement de la NORB consiste en une administration de <strong>méthylprednisolone IV à la dose de 1 g/jour pendant 3 à 5 jours</strong>. La corticothérapie orale seule est contre-indiquée en raison d'un risque élevé de rechutes visuelles.</p>"},{"i":"c6214f880693","n":104,"o":"104-18","u":"Identifier une urgence","t":"Savoir qu’une NORB menace le pronostic visuel et est une urgence diagnostique","q":"Quels signes cliniques chez un adulte jeune doivent faire suspecter une névrite optique rétrobulbaire (NORB) et imposer un bilan sans délai ?","a":"<ul><li>Une <strong>baisse d'acuité visuelle unilatérale</strong>.</li><li>Une baisse d'acuité visuelle <strong>subaiguë</strong> (évoluant sur des heures à des jours).</li><li>Une baisse d'acuité visuelle <strong>douloureuse aux mouvements oculaires</strong>.</li></ul>"},{"i":"58707fa8e4a6","n":104,"o":"104-3","u":"Diagnostic positif","t":"Citer les principaux symptômes révélateurs de la SEP","q":"Quelle est l'atteinte oculaire typique révélatrice de la sclérose en plaques ?","a":"<p>La <strong>névrite optique rétrobulbaire (NORB)</strong> est une atteinte oculaire typique. Elle se présente comme une <strong>baisse d'acuité visuelle unilatérale subaiguë douloureuse</strong>.</p>"},{"i":"d301a586ea33","n":104,"o":"104-3","u":"Diagnostic positif","t":"Citer les principaux symptômes révélateurs de la SEP","q":"Quelle est la présentation clinique générale qui doit faire évoquer une sclérose en plaques (SEP) chez un patient ?","a":"<p>La sclérose en plaques doit être évoquée devant un <strong>déficit neurologique d'installation subaiguë</strong> chez un <strong>adulte jeune</strong>.</p>"},{"i":"ea7fe4617488","n":104,"o":"104-3","u":"Diagnostic positif","t":"Citer les principaux symptômes révélateurs de la SEP","q":"Quels sont les grands syndromes neurologiques qui doivent faire fortement douter du diagnostic de sclérose en plaques s'ils sont présents ?","a":"<p>Certains signes sont rares dans la SEP et doivent faire fortement douter du diagnostic :<ul><li><strong>Hémianopsie latérale homonyme</strong></li><li><strong>Cécité</strong> ou <strong>surdité</strong> complète</li><li>Atteinte du <strong>système nerveux périphérique</strong></li><li><strong>Syndrome extrapyramidal</strong></li><li><strong>Aphasie</strong> ou <strong>apraxie</strong>.</li></ul></p>"},{"i":"f35cdcec18cf","n":104,"o":"104-3","u":"Diagnostic positif","t":"Citer les principaux symptômes révélateurs de la SEP","q":"Quels sont les signes d'une atteinte du tronc cérébral pouvant révéler une sclérose en plaques ?","a":"<p>Une atteinte du tronc cérébral peut se manifester par :<ul><li>Des <strong>vertiges</strong> (syndrome vestibulaire central)</li><li>Une <strong>diplopie</strong></li><li>Une <strong>ophtalmoplégie internucléaire</strong>.</li></ul></p>"},{"i":"f91c9eb7f9cf","n":104,"o":"104-3","u":"Diagnostic positif","t":"Citer les principaux symptômes révélateurs de la SEP","q":"Quels sont les symptômes fréquents d'une atteinte médullaire révélatrice de la sclérose en plaques ?","a":"<p>Une atteinte médullaire peut se manifester par une <ul><li><strong>myélite partielle</strong></li><li>Le <strong>signe de Lhermitte</strong>, caractérisé par des décharges électriques le long du rachis à la flexion du cou.</li></ul></p>"},{"i":"0313c9d9bac0","n":104,"o":"104-4","u":"Diagnostic positif","t":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","q":"Quelles sont les caractéristiques de la douleur dans la névrite optique rétrobulbaire (NORB) ?","a":"<ul><li>Présente dans <strong>80 % des cas</strong>.</li><li>Elle est <strong>rétro-oculaire</strong>.</li><li>Elle est <strong>augmentée aux mouvements oculaires</strong>, ce qui oriente vers un caractère inflammatoire.</li><li>L'œil lui-même est <strong>blanc et indolore</strong>.</li></ul>"},{"i":"0844072c71fb","n":104,"o":"104-4","u":"Diagnostic positif","t":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","q":"Quelle est la définition et la prévalence de la névrite optique rétrobulbaire (NORB) dans le cadre de la sclérose en plaques ?","a":"<p>La NORB est une <strong>neuropathie optique inflammatoire démyélinisante</strong>. Elle est une manifestation fréquente et <strong>inaugurale dans 20 à 25 % des cas</strong> de la sclérose en plaques.</p>"},{"i":"6131c716a1cc","n":104,"o":"104-4","u":"Diagnostic positif","t":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","q":"Quelles sont les particularités du champ visuel et de la vision des couleurs en cas de névrite optique rétrobulbaire (NORB) ?","a":"<ul><li><strong>Champ visuel</strong> : présence d'un <strong>scotome central ou cæcocentral</strong> du côté atteint.</li><li><strong>Vision des couleurs</strong> : présence d'une <strong>dyschromatopsie d'axe rouge-vert</strong> (mise en évidence par le test de Farnsworth).</li></ul>"},{"i":"82a9eb490a9e","n":104,"o":"104-4","u":"Diagnostic positif","t":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","q":"Quels sont les signes objectifs à l'examen de l'œil et du fond d'œil lors d'une névrite optique rétrobulbaire (NORB) ?","a":"<ul><li><strong>Examen de l'œil</strong> : l'œil est <strong>blanc et indolore</strong>.</li><li><strong>Réflexe photomoteur</strong> : présence quasi constante d'un <strong>déficit pupillaire afférent relatif</strong> (pupille de Marcus Gunn) du côté atteint.</li><li><strong>Fond d'œil</strong> : <strong>normal dans 70 % des cas</strong> (forme rétrobulbaire) ; un œdème papillaire modéré (papillite) peut être retrouvé dans 10 à 30 % des cas.</li></ul>"},{"i":"c0b980d32c08","n":104,"o":"104-4","u":"Diagnostic positif","t":"Connaître les signes de la névrite optique rétrobulbaire (NORB)","q":"Quelles sont les caractéristiques de la baisse d'acuité visuelle au cours d'une névrite optique rétrobulbaire (NORB) ?","a":"<ul><li><strong>Installation</strong> : rapidement progressive sur quelques heures à jours (<strong>PAS brutale</strong>).</li><li><strong>Latéralité</strong> : le plus souvent <strong>unilatérale</strong>.</li><li><strong>Importance</strong> : variable, mais souvent marquée (peut être inférieure à 1/10).</li></ul>"},{"i":"49e69eab4fc9","n":104,"o":"104-5","u":"Définition","t":"Savoir définir une poussée de la maladie","q":"Comment définit-on une poussée de sclérose en plaques ?","a":"<p>Une poussée de SEP est définie par l'<strong>apparition de nouveaux symptômes</strong>, la <strong>réapparition d'anciens symptômes</strong>, ou l'<strong>aggravation de symptômes pré-existants</strong>.</p>"},{"i":"5a8bd19bab53","n":104,"o":"104-5","u":"Définition","t":"Savoir définir une poussée de la maladie","q":"Quels sont les critères temporels essentiels caractérisant une poussée de sclérose en plaques ?","a":"<ul><li>L'installation est <strong>subaiguë</strong>, sur quelques heures à jours.</li><li>La durée des symptômes doit être <strong>supérieure à 24 heures</strong>.</li><li>Deux poussées sont séparées par un intervalle <strong>supérieur ou égal à 1 mois</strong>.</li><li>La récupération est <strong>plus ou moins complète</strong>.</li></ul>"},{"i":"ab703ae6c8b6","n":104,"o":"104-5","u":"Définition","t":"Savoir définir une poussée de la maladie","q":"Quelles situations ne doivent pas être considérées comme une poussée de sclérose en plaques ?","a":"<p>Ne doivent <strong>pas</strong> être considérés comme une poussée de sclérose en plaques :</p><ul><li>La <strong>fatigue isolée</strong>.</li><li>Les symptômes survenant dans un <strong>contexte fébrile</strong>, également appelés « pseudo-poussée » (phénomène d'Uhthoff).</li></ul>"},{"i":"17ae1df1f300","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Sur quel référentiel s'appuie le diagnostic de la sclérose en plaques (SEP) ?","a":"<p>Le diagnostic de la SEP repose sur les <strong>critères de McDonald 2017</strong>.</p>"},{"i":"1bef8334dd95","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Dans quel cas le diagnostic de sclérose en plaques (SEP) peut-il être posé dès la première poussée ?","a":"<p>Le diagnostic de SEP peut être posé dès la première poussée si la <strong>dissémination temporelle est déjà présente</strong>, se manifestant par la détection de <strong>lésions d'âges différents à l'IRM</strong>.</p>"},{"i":"3241be9676ce","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Quel est le principe général du diagnostic de la sclérose en plaques (SEP) ?","a":"<p>Le diagnostic de la SEP n'est pas basé sur un examen spécifique, mais sur un <strong>faisceau d'arguments</strong>, combinant des critères de dissémination spatiale et temporelle, et l'élimination des diagnostics différentiels.</p>"},{"i":"80b56e015fd7","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Comment est définie la dissémination spatiale dans le diagnostic de la sclérose en plaques (SEP) ?","a":"<p>La dissémination spatiale est définie par l'atteinte de <strong>plusieurs zones du système nerveux central (SNC)</strong>, mise en évidence cliniquement (par exemple, par l'association d'une névrite optique et d'un syndrome pyramidal) ou par l'IRM. Le critère est rempli si l'IRM met en évidence <strong>au moins une lésion dans au moins deux des quatre zones stratégiques</strong> du SNC.</p>"},{"i":"9f4a70b6825b","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Comment est définie la dissémination temporelle dans le diagnostic de la sclérose en plaques (SEP) ?","a":"<p>La dissémination temporelle correspond à une <strong>succession d'épisodes dans le temps</strong>. Elle peut être objectivée par :</p><ul><li>Une <strong>nouvelle IRM</strong> réalisée au moins 3 mois après la première.</li><li>L'association de <strong>lésions prenant le gadolinium et de lésions ne le prenant pas</strong> sur une même IRM.</li><li>La présence de <strong>bandes oligoclonales dans le liquide céphalorachidien (LCS)</strong>, qui peut remplacer ce critère et permettre un diagnostic plus précoce.</li></ul>"},{"i":"ab1dd2220474","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Comment s'assurer de l'absence d'arguments contre le diagnostic de sclérose en plaques (SEP) ?","a":"<p>Il est nécessaire de s'assurer de l'<strong>absence d'altération de l'état général</strong> et de l'<strong>absence de meilleure explication alternative</strong> aux symptômes présentés. L'exclusion rigoureuse des diagnostics différentiels est un élément essentiel du diagnostic de SEP.</p>"},{"i":"cffe9bec8489","n":104,"o":"104-6","u":"Diagnostic positif","t":"Connaître les principaux arguments du diagnostic de SEP","q":"Quel critère temporel spécifique s'applique à la forme progressive d'emblée de la sclérose en plaques (SEP) ?","a":"<p>Pour la forme progressive d'emblée de la SEP, le critère temporel spécifique est une <strong>évolution des symptômes sur plus d'un an</strong>.</p>"}]};